  'Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
const MONO =
  '"SFMono-Regular", Consolas, "Liberation Mono", ui-monospace, monospace';

const wave = (frame: number, period: number, phase = 0) =>
  Math.sin(((frame + phase) / period) * Math.PI * 2);

const hash = (index: number, salt: number) => {
  const value = Math.sin(index * 127.1 + salt * 311.7) * 43758.5453123;
  return value - Math.floor(value);
};

const SPECKS = Array.from({length: 360}, (_, index) => ({
  left: hash(index, 1) * 100,
  top: hash(index, 2) * 100,
  size: 0.7 + hash(index, 3) * 0.7,
  opacity: 0.14 + hash(index, 4) * 0.08,
}));

