const SectionTitle: React.FC<{
  eyebrow: string;
  title: string;
  trailing?: React.ReactNode;
}> = ({eyebrow, title, trailing}) => (
  <div
    style={{
      position: 'relative',
      display: 'flex',
      alignItems: 'flex-start',
      justifyContent: 'space-between',
      marginBottom: 22,
    }}
  >
    <div>
      <div
        style={{
          color: COLORS.cyan,
          fontSize: 13,
          fontWeight: 800,
          letterSpacing: 2.4,
          textTransform: 'uppercase',
          marginBottom: 7,
        }}
      >
        {eyebrow}
      </div>
      <div
        style={{
          color: COLORS.text,
          fontSize: 25,
          fontWeight: 680,
          letterSpacing: -0.5,
        }}
      >
        {title}
      </div>
    </div>
    {trailing}
  </div>
);

const LivePill: React.FC<{frame: number}> = ({frame}) => {
  const glow = 0.42 + (wave(frame, 90) + 1) * 0.18;
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 9,
        height: 34,
        padding: '0 13px',
        borderRadius: 999,
        color: COLORS.cyanSoft,
        background: 'rgba(72,231,209,0.08)',
        border: '1px solid rgba(72,231,209,0.18)',
        fontSize: 12,
        fontWeight: 800,
        letterSpacing: 1.4,
      }}
    >
      <span
        style={{
          width: 8,
          height: 8,
          borderRadius: 99,
          background: COLORS.cyan,
          boxShadow: `0 0 18px rgba(72,231,209,${glow})`,
        }}
      />
      LIVE
    </div>
  );
};

const ShieldIcon: React.FC<{size?: number; color?: string}> = ({
  size = 28,
  color = COLORS.cyan,
}) => (
  <svg width={size} height={size} viewBox="0 0 32 32" fill="none">
    <path
      d="M16 3.2 27 7.4v7.2c0 7.2-4.4 11.7-11 14.2C9.4 26.3 5 21.8 5 14.6V7.4L16 3.2Z"
      stroke={color}
      strokeWidth="2"
      fill="rgba(72,231,209,0.08)"
    />
    <path
      d="m11.2 16.1 3.1 3.1 6.8-7"
      stroke={color}
      strokeWidth="2.2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const SeverityTag: React.FC<{
  label: string;
  color: string;
  background: string;
}> = ({label, color, background}) => (
  <div
    style={{
      height: 28,
      padding: '0 10px',
      borderRadius: 9,
      display: 'flex',
      alignItems: 'center',
      color,
      background,
      border: `1px solid ${color}30`,
      fontSize: 11,
      fontWeight: 800,
      letterSpacing: 0.8,
    }}
  >
    {label}
  </div>
);

const INCIDENTS = [
  {name: 'Cloud gateway', region: 'Frankfurt · DE', type: 'DDoS', color: COLORS.red},
  {name: 'Identity service', region: 'Virginia · US', type: 'IAM', color: COLORS.amber},
  {name: 'API edge', region: 'Singapore · SG', type: 'BOT', color: COLORS.violet},
  {name: 'Email security', region: 'London · UK', type: 'PHISH', color: COLORS.amber},
  {name: 'Data cluster', region: 'Tokyo · JP', type: 'MAL', color: COLORS.red},
];

const IncidentRow: React.FC<{
  item: (typeof INCIDENTS)[number];
  index: number;
  frame: number;
}> = ({item, index, frame}) => {
  const pulse = Math.max(0, wave(frame, 150, index * 29));
  const age = 8 + ((Math.floor((frame + index * 83) / 90) * 7 + index * 11) % 48);
  return (
    <div
      style={{
        height: 88,
        borderRadius: 16,
        position: 'relative',
        display: 'flex',
        alignItems: 'center',
        padding: '0 14px 0 17px',
        background: `linear-gradient(90deg, ${item.color}0F, rgba(255,255,255,0.018))`,
        border: `1px solid ${item.color}1C`,
        boxShadow: `inset 3px 0 0 ${item.color}${Math.round(50 + pulse * 80)
          .toString(16)
          .padStart(2, '0')}`,
      }}
    >
      <div style={{flex: 1, minWidth: 0}}>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 9,
            marginBottom: 8,
          }}
        >
          <div
            style={{
              width: 8,
              height: 8,
              borderRadius: 8,
              background: item.color,
              boxShadow: `0 0 ${10 + pulse * 8}px ${item.color}`,
            }}
          />
          <div
            style={{
              color: COLORS.text,
              fontSize: 17,
              lineHeight: 1,
              fontWeight: 650,
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }}
          >
            {item.name}
          </div>
        </div>
        <div
          style={{
            color: COLORS.muted,
            fontFamily: MONO,
            fontSize: 12,
            letterSpacing: 0.1,
          }}
        >
          {item.region} · {age}s ago
        </div>
      </div>
      <SeverityTag
        label={item.type}
        color={item.color}
        background={`${item.color}12`}
      />
    </div>
  );
};

const IncidentFeed: React.FC<{frame: number}> = ({frame}) => {
  const active = 27 + Math.round(wave(frame, 450) * 2 + wave(frame, 225, 30));
  return (
    <GlassPanel style={{left: 74, top: 232, width: 410, height: 714}}>
      <div style={{position: 'relative', padding: '28px 26px'}}>
        <SectionTitle
          eyebrow="Threat activity"
          title="Active incidents"
          trailing={<LivePill frame={frame} />}
        />

        <div
          style={{
            height: 92,
            borderRadius: 18,
            display: 'flex',
            alignItems: 'center',
            padding: '0 18px',
            marginBottom: 18,
            background:
              'linear-gradient(105deg, rgba(72,231,209,0.10), rgba(88,166,255,0.05))',
            border: '1px solid rgba(72,231,209,0.14)',
          }}
        >
          <div>
            <div
              style={{
                color: COLORS.text,
                fontSize: 40,
                fontWeight: 750,
                letterSpacing: -1.6,
                lineHeight: 1,
              }}
            >
              {active}
            </div>
            <div
              style={{
                color: COLORS.muted,
                fontSize: 12,
                fontWeight: 700,
                letterSpacing: 1.2,
                marginTop: 8,
              }}
            >
              OPEN EVENTS
            </div>
          </div>
          <div style={{marginLeft: 'auto', display: 'flex', gap: 8}}>
            <SeverityTag
              label="5 CRITICAL"
              color={COLORS.red}
              background="rgba(255,95,120,0.08)"
            />
            <SeverityTag
              label="8 HIGH"
              color={COLORS.amber}
              background="rgba(255,190,85,0.08)"
            />
          </div>
        </div>

        <div style={{display: 'flex', flexDirection: 'column', gap: 10}}>
          {INCIDENTS.map((item, index) => (
            <IncidentRow
              key={item.name}
              item={item}
              index={index}
              frame={frame}
            />
          ))}
        </div>
      </div>
    </GlassPanel>
  );
};

