const DEG = Math.PI / 180;
const GLOBE_CENTER = 350;
const GLOBE_RADIUS = 320;
const GLOBE_TILT = 10 * DEG;
const GLOBE_ROTATION_FRAMES = 900;
const SCAN_ROTATION_FRAMES = 225;
const SCAN_BASE_ANGLE = -50.2;

const wrap = (value: number, modulus: number) =>
  ((value % modulus) + modulus) % modulus;

const normalizeAngle = (angle: number) => wrap(angle, 360);

const angularDistance = (first: number, second: number) => {
  const distance = Math.abs(normalizeAngle(first) - normalizeAngle(second));
  return Math.min(distance, 360 - distance);
};

const centerLongitudeAtFrame = (frame: number) =>
  -30 - (wrap(frame, GLOBE_ROTATION_FRAMES) / GLOBE_ROTATION_FRAMES) * 360;

const scanAngleAtFrame = (frame: number) =>
  normalizeAngle(
    SCAN_BASE_ANGLE +
      (wrap(frame, SCAN_ROTATION_FRAMES) / SCAN_ROTATION_FRAMES) * 360,
  );

const projectGeoPoint = (
  [longitude, latitude]: GeoPoint,
  centerLongitude: number,
): ProjectedGeoPoint => {
  const lambda = (longitude - centerLongitude) * DEG;
  const phi = latitude * DEG;
  const sinPhi = Math.sin(phi);
  const cosPhi = Math.cos(phi);
  const sinTilt = Math.sin(GLOBE_TILT);
  const cosTilt = Math.cos(GLOBE_TILT);
  const depth =
    sinTilt * sinPhi + cosTilt * cosPhi * Math.cos(lambda);

  return {
    x: GLOBE_CENTER + GLOBE_RADIUS * cosPhi * Math.sin(lambda),
    y:
      GLOBE_CENTER -
      GLOBE_RADIUS *
        (cosTilt * sinPhi - sinTilt * cosPhi * Math.cos(lambda)),
    depth,
    visible: depth > 0.015,
  };
};

const makeLinePath = (lines: GeoPoint[][], centerLongitude: number) => {
  const path: string[] = [];
  lines.forEach((line) => {
    let drawing = false;
    line.forEach((coordinate) => {
      const point = projectGeoPoint(coordinate, centerLongitude);
      if (!point.visible) {
        drawing = false;
        return;
      }
      path.push(
        `${drawing ? 'L' : 'M'}${point.x.toFixed(1)} ${point.y.toFixed(1)}`,
      );
      drawing = true;
    });
  });
  return path.join('');
};

const makeLandDotPath = (centerLongitude: number) => {
  const path: string[] = [];
  LAND_DOTS.forEach((coordinate, index) => {
    if (index % 2 !== 0) return;
    const point = projectGeoPoint(coordinate, centerLongitude);
    if (!point.visible) return;
    const size = 1.2 + Math.max(0, point.depth) * 1.55;
    path.push(
      `M${(point.x - size / 2).toFixed(1)} ${(point.y - size / 2).toFixed(
        1,
      )}h${size.toFixed(1)}v${size.toFixed(1)}h-${size.toFixed(1)}Z`,
    );
  });
  return path.join('');
};

const GRATICULE_LINES: GeoPoint[][] = [
  ...[-60, -30, 0, 30, 60].map((latitude) =>
    Array.from({length: 73}, (_, index) => [-180 + index * 5, latitude] as GeoPoint),
  ),
  ...Array.from({length: 12}, (_, longitudeIndex) => {
    const longitude = -180 + longitudeIndex * 30;
    return Array.from(
      {length: 35},
      (_, latitudeIndex) => [longitude, -85 + latitudeIndex * 5] as GeoPoint,
    );
  }),
];

