export const Motion: React.FC = () => {
  const frame = useCurrentFrame();
  const {width, height} = useVideoConfig();
  const scale = Math.min(width / 1920, height / 1080);
  const offsetX = (width - 1920 * scale) / 2;
  const offsetY = (height - 1080 * scale) / 2;

  return (
    <AbsoluteFill style={{background: COLORS.bg, fontFamily: FONT}}>
      <div
        style={{
          position: 'absolute',
          left: offsetX,
          top: offsetY,
          width: 1920,
          height: 1080,
          transform: `scale(${scale})`,
          transformOrigin: 'top left',
          overflow: 'hidden',
        }}
      >
        <Background />
        <Header frame={frame} />
        <IncidentFeed frame={frame} />
        <GeoGlobe frame={frame} />
        <CentralCaption frame={frame} />
        <RiskSummary frame={frame} />
      </div>
    </AbsoluteFill>
  );
};
